class Solution {
public:
    vector<int> closestRoom(vector<vector<int>>& rooms, vector<vector<int>>& queries) {
        int n = rooms.size();
        int k = queries.size();

        sort(rooms.begin(), rooms.end(), [](const vector<int>& a, const vector<int>& b){
            return a[1] > b[1];
        });

        vector<int> qidx(k);
        for (int i = 0; i < k; i++) qidx[i] = i;
        sort(qidx.begin(), qidx.end(), [&](int a, int b){
            return queries[a][1] > queries[b][1];
        });

        vector<int> ans(k, -1);
        set<int> ids;
        int ri = 0;
        for (int i = 0; i < k; i++) {
            int qi = qidx[i];
            int preferred = queries[qi][0];
            int minSize = queries[qi][1];

            while (ri < n && rooms[ri][1] >= minSize) {
                ids.insert(rooms[ri][0]);
                ri++;
            }

            if (ids.empty()) {
                ans[qi] = -1;
                continue;
            }

            auto it = ids.lower_bound(preferred);
            int best = -1;
            int bestDiff = INT_MAX;

            if (it != ids.end()) {
                int cand = *it;
                int diff = abs(cand - preferred);
                if (diff < bestDiff || (diff == bestDiff && cand < best)) {
                    bestDiff = diff;
                    best = cand;
                }
            }
            if (it != ids.begin()) {
                --it;
                int cand = *it;
                int diff = abs(cand - preferred);
                if (diff < bestDiff || (diff == bestDiff && cand < best)) {
                    bestDiff = diff;
                    best = cand;
                }
            }
            ans[qi] = best;
        }
        return ans;
    }
};
